import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import API from '../services/api';

export default function Documents() {
  const { user } = useAuth();
  const [docs, setDocs] = useState([]);
  const [categories, setCategories] = useState([]);
  const [filters, setFilters] = useState({ search: '', category: '', department: '', startDate: '', endDate: '' });
  const [pagination, setPagination] = useState({ page: 1, pages: 1, total: 0 });
  const [selected, setSelected] = useState(null);
  const [versionFile, setVersionFile] = useState(null);
  const [versionNotes, setVersionNotes] = useState('');
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState('');

  const canManage = ['Admin', 'Record Manager'].includes(user.role);

  const fetchDocs = useCallback(async (page = 1) => {
    setLoading(true);
    try {
      const params = { page, limit: 10, ...Object.fromEntries(Object.entries(filters).filter(([, v]) => v)) };
      const { data } = await API.get('/documents', { params });
      setDocs(data.docs);
      setPagination({ page: data.page, pages: data.pages, total: data.total });
    } catch {}
    setLoading(false);
  }, [filters]);

  useEffect(() => {
    API.get('/categories').then(r => setCategories(r.data)).catch(() => {});
  }, []);

  useEffect(() => { fetchDocs(1); }, [fetchDocs]);

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this document?')) return;
    try {
      await API.delete(`/documents/${id}`);
      fetchDocs(pagination.page);
    } catch (err) { setMsg(err.response?.data?.message || 'Delete failed'); }
  };

  const handleDownload = async (doc) => {
    try {
      const res = await API.get(`/documents/${doc._id}/download`, { responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const a = document.createElement('a');
      a.href = url; a.download = doc.originalName || doc.title;
      a.click(); window.URL.revokeObjectURL(url);
    } catch { setMsg('Download failed'); }
  };

  const handleNewVersion = async (docId) => {
    if (!versionFile) return setMsg('Select a file for new version');
    const fd = new FormData();
    fd.append('file', versionFile);
    fd.append('notes', versionNotes);
    try {
      await API.post(`/documents/${docId}/version`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      setMsg('New version uploaded!');
      setVersionFile(null); setVersionNotes('');
      const { data } = await API.get(`/documents/${docId}`);
      setSelected(data);
      fetchDocs(pagination.page);
    } catch (err) { setMsg(err.response?.data?.message || 'Version upload failed'); }
  };

  const handleRestore = async (docId, versionNumber) => {
    try {
      await API.put(`/documents/${docId}/restore`, { versionNumber });
      setMsg(`Restored to version ${versionNumber}`);
      const { data } = await API.get(`/documents/${docId}`);
      setSelected(data);
    } catch { setMsg('Restore failed'); }
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.heading}>Documents</h2>
      {msg && <p style={styles.msg}>{msg}</p>}

      {/* Filters */}
      <div style={styles.filterRow}>
        <input style={styles.filterInput} placeholder="Search..." value={filters.search}
          onChange={e => setFilters({ ...filters, search: e.target.value })} />
        <select style={styles.filterInput} value={filters.category}
          onChange={e => setFilters({ ...filters, category: e.target.value })}>
          <option value="">All Categories</option>
          {categories.map(c => <option key={c._id} value={c._id}>{c.name}</option>)}
        </select>
        <input style={styles.filterInput} placeholder="Department" value={filters.department}
          onChange={e => setFilters({ ...filters, department: e.target.value })} />
        <input style={styles.filterInput} type="date" value={filters.startDate}
          onChange={e => setFilters({ ...filters, startDate: e.target.value })} />
        <input style={styles.filterInput} type="date" value={filters.endDate}
          onChange={e => setFilters({ ...filters, endDate: e.target.value })} />
        <button style={styles.clearBtn} onClick={() => setFilters({ search: '', category: '', department: '', startDate: '', endDate: '' })}>Clear</button>
      </div>

      <p style={{ color: '#666', fontSize: '13px' }}>Total: {pagination.total} documents</p>

      {loading ? <p>Loading...</p> : (
        <table style={styles.table}>
          <thead>
            <tr style={styles.thead}>
              <th style={styles.th}>Title</th>
              <th style={styles.th}>Category</th>
              <th style={styles.th}>Department</th>
              <th style={styles.th}>Version</th>
              <th style={styles.th}>Uploaded By</th>
              <th style={styles.th}>Date</th>
              <th style={styles.th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {docs.map(doc => (
              <tr key={doc._id} style={styles.tr}>
                <td style={styles.td}>{doc.title}</td>
                <td style={styles.td}>{doc.category?.name || '-'}</td>
                <td style={styles.td}>{doc.department}</td>
                <td style={styles.td}>v{doc.currentVersion}</td>
                <td style={styles.td}>{doc.uploadedBy?.name || '-'}</td>
                <td style={styles.td}>{new Date(doc.createdAt).toLocaleDateString()}</td>
                <td style={styles.td}>
                  <button style={styles.actionBtn('#1565c0')} onClick={() => handleDownload(doc)}>Download</button>
                  <button style={styles.actionBtn('#00695c')} onClick={async () => { const { data } = await API.get(`/documents/${doc._id}`); setSelected(data); setMsg(''); }}>Details</button>
                  {canManage && <button style={styles.actionBtn('#c62828')} onClick={() => handleDelete(doc._id)}>Delete</button>}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* Pagination */}
      <div style={styles.pagination}>
        {Array.from({ length: pagination.pages }, (_, i) => i + 1).map(p => (
          <button key={p} style={{ ...styles.pageBtn, background: p === pagination.page ? '#1a237e' : '#e8eaf6', color: p === pagination.page ? '#fff' : '#333' }}
            onClick={() => fetchDocs(p)}>{p}</button>
        ))}
      </div>

      {/* Document Detail Modal */}
      {selected && (
        <div style={styles.overlay} onClick={() => setSelected(null)}>
          <div style={styles.modal} onClick={e => e.stopPropagation()}>
            <h3 style={{ color: '#1a237e' }}>{selected.title}</h3>
            <p><strong>Department:</strong> {selected.department}</p>
            <p><strong>Tags:</strong> {selected.tags?.join(', ') || 'None'}</p>
            <p><strong>Current Version:</strong> v{selected.currentVersion}</p>
            <p><strong>File:</strong> {selected.originalName}</p>
            <p><strong>Size:</strong> {(selected.fileSize / 1024).toFixed(1)} KB</p>

            <h4>Version History</h4>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
              <thead><tr style={{ background: '#e8eaf6' }}>
                <th style={styles.th}>Version</th><th style={styles.th}>Date</th><th style={styles.th}>Notes</th>
                {canManage && <th style={styles.th}>Action</th>}
              </tr></thead>
              <tbody>
                {selected.versions?.map(v => (
                  <tr key={v.versionNumber} style={styles.tr}>
                    <td style={styles.td}>v{v.versionNumber}</td>
                    <td style={styles.td}>{new Date(v.uploadedAt).toLocaleDateString()}</td>
                    <td style={styles.td}>{v.notes || '-'}</td>
                    {canManage && <td style={styles.td}>
                      {v.versionNumber !== selected.currentVersion &&
                        <button style={styles.actionBtn('#e65100')} onClick={() => handleRestore(selected._id, v.versionNumber)}>Restore</button>}
                    </td>}
                  </tr>
                ))}
              </tbody>
            </table>

            {canManage && (
              <div style={{ marginTop: '16px' }}>
                <h4>Upload New Version</h4>
                <input type="file" accept=".pdf,.docx,.xlsx,.jpg,.jpeg" onChange={e => setVersionFile(e.target.files[0])} style={{ marginBottom: '8px' }} />
                <input style={{ ...styles.filterInput, width: '100%', marginBottom: '8px' }} placeholder="Version notes"
                  value={versionNotes} onChange={e => setVersionNotes(e.target.value)} />
                <button style={styles.actionBtn('#1a237e')} onClick={() => handleNewVersion(selected._id)}>Upload Version</button>
              </div>
            )}
            <button style={{ ...styles.actionBtn('#555'), marginTop: '12px' }} onClick={() => setSelected(null)}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  container: { padding: '24px', maxWidth: '1200px', margin: '0 auto' },
  heading: { color: '#1a237e', marginBottom: '16px' },
  filterRow: { display: 'flex', gap: '8px', flexWrap: 'wrap', marginBottom: '16px' },
  filterInput: { padding: '8px', border: '1px solid #ccc', borderRadius: '4px', fontSize: '13px' },
  clearBtn: { padding: '8px 14px', background: '#757575', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' },
  table: { width: '100%', borderCollapse: 'collapse', background: '#fff', borderRadius: '8px', overflow: 'hidden', boxShadow: '0 1px 6px rgba(0,0,0,0.1)' },
  thead: { background: '#1a237e', color: '#fff' },
  th: { padding: '10px 12px', textAlign: 'left', fontSize: '13px' },
  tr: { borderBottom: '1px solid #eee' },
  td: { padding: '10px 12px', fontSize: '13px' },
  actionBtn: (bg) => ({ background: bg, color: '#fff', border: 'none', padding: '4px 10px', borderRadius: '4px', cursor: 'pointer', marginRight: '4px', fontSize: '12px' }),
  pagination: { display: 'flex', gap: '6px', marginTop: '16px' },
  pageBtn: { padding: '6px 12px', border: 'none', borderRadius: '4px', cursor: 'pointer' },
  msg: { color: '#1a237e', background: '#e8eaf6', padding: '8px', borderRadius: '4px', marginBottom: '12px' },
  overlay: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  modal: { background: '#fff', padding: '24px', borderRadius: '8px', maxWidth: '700px', width: '90%', maxHeight: '80vh', overflowY: 'auto' }
};
